import { spawn } from 'node:child_process';
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'], { env: { ...process.env, GBRAIN_HOME: '/harness-state' }, stdio: ['pipe','pipe','pipe'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0,i); buf = buf.slice(i+1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', () => {});
const rpc = (method, params) => new Promise(r => { const n = ++id; waiters.set(n, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const show = (label, m) => { const t = m.result?.content?.map(c => c.text).join('\n') ?? JSON.stringify(m.error ?? m.result); console.log(`== ${label}\n${t.slice(0, 1500)}`); };
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t => t.name).join(', '));
show('remember (MCP)', await rpc('tools/call', { name: 'remember', arguments: { fact: 'GBrain MCP round-trip test note for the OpenClaw install (generic, not about the user)', entity: 'gbrain-install-check', provenance: 'install-check', content_origin: 'inferred' } }));
show('recall (MCP)', await rpc('tools/call', { name: 'recall', arguments: { query: 'gbrain install check', entity: 'gbrain-install-check' } }));
p.kill(); process.exit(0);

